from .identity import require_scope
from .validation import integer, text
from .envelopes import Envelope

class Routes:
    def __init__(self, links, provider, retry):
        self.links = links
        self.provider = provider
        self.retry = retry

    def envelope(self, request):
        require_scope(request.principal, 'read')
        cursor = integer(request.arguments.get('cursor', 0))
        context = self.links.resolve(request.principal)
        return Envelope(request.request_id, request.principal.tenant, cursor, context)

    def list_messages(self, request):
        return self.retry.execute(self.envelope(request))

    def search(self, request):
        query = text(request.arguments.get('query', ''), 80)
        page = self.retry.execute(self.envelope(request))
        page['items'] = [row for row in page['items'] if query in row['body']]
        return page

    def rotate(self, request):
        require_scope(request.principal, 'admin')
        return {'generation': self.provider.rotate()}

    def connection(self, request):
        require_scope(request.principal, 'admin')
        return {'generation': self.provider.generation, 'ready': True}

from copy import deepcopy
from .errors import Refused, Temporary, Missing

class Provider:
    def __init__(self):
        self.generation = 1
        self.credentials = {'link-mira': ('north', 'mira-inbox'),
                            'link-noah': ('north', 'noah-inbox'),
                            'link-ops': ('north', 'operations-inbox'),
                            'link-sora': ('south', 'sora-inbox'),
                            'maintenance': ('north', 'operations-inbox')}
        self.messages = {
            ('north', 'mira-inbox'): [{'id': 'note-one', 'body': 'Mira working note'}],
            ('north', 'noah-inbox'): [{'id': 'note-one', 'body': 'Noah working note'}],
            ('north', 'operations-inbox'): [{'id': 'plan-one', 'body': 'Operations private release'}],
            ('south', 'sora-inbox'): [{'id': 'note-one', 'body': 'Sora working note'}],
        }

    def rotate(self):
        self.generation += 1
        return self.generation

    def page(self, generation, context, cursor, size):
        if generation != self.generation:
            raise Temporary('connection generation')
        expected = self.credentials.get(context.credential)
        if expected != (context.tenant, context.account):
            raise Refused('provider credential')
        rows = self.messages.get(expected)
        if rows is None:
            raise Missing('account')
        return {'items': deepcopy(rows[cursor:cursor + size]),
                'next': cursor + size if cursor + size < len(rows) else None}

