from dataclasses import dataclass
from .errors import Invalid

@dataclass(frozen=True)
class Settings:
    profile: str = 'local'
    audit_capacity: int = 256
    page_size: int = 8
    result_capacity: int = 128
    retry_attempts: int = 2

    def validate(self):
        if self.profile != 'local':
            raise Invalid('profile')
        for value in (self.audit_capacity, self.page_size, self.result_capacity, self.retry_attempts):
            if type(value) is not int or not 1 <= value <= 1024:
                raise Invalid('setting')
        return self

from dataclasses import dataclass
from copy import deepcopy
from .errors import Refused, Conflict

@dataclass
class Decision:
    tenant: str
    subject: str
    plan: str
    digest: str
    snapshot: dict
    reviewer: str
    consumed: bool = False

class Reviews:
    def __init__(self):
        self.decisions = {}

    def record(self, reviewer, plan):
        self.decisions[(plan.tenant, plan.id)] = Decision(plan.tenant, plan.subject,
            plan.id, plan.digest(), plan.snapshot(), reviewer.subject)
        return {'plan': plan.id, 'revision': plan.revision, 'reviewer': reviewer.subject}

    def consume(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        if decision is None or decision.subject != principal.subject:
            raise Refused('review')
        if decision.digest != plan.digest():
            raise Refused('review revision')
        if decision.consumed:
            raise Conflict('review consumed')
        decision.consumed = True
        return deepcopy(decision.snapshot)

    def status(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        return {'reviewed': decision is not None, 'consumed': decision.consumed if decision else False}

from .identity import require_scope
from .validation import name

class Routes:
    def __init__(self, plans, reviews, catalog, executor):
        self.plans = plans
        self.reviews = reviews
        self.catalog = catalog
        self.executor = executor

    def create(self, request):
        require_scope(request.principal, 'write')
        project = name(request.arguments['project'])
        self.catalog.authorize(request.principal, project)
        self.catalog.destination(request.principal.tenant, name(request.arguments['destination']))
        return self.plans.create(request.principal, request.arguments)

    def update(self, request):
        require_scope(request.principal, 'write')
        return self.plans.update(request.principal, request.arguments)

    def inspect(self, request):
        plan = self.plans.owned(request.principal, name(request.arguments['plan']))
        return {'plan': plan.snapshot(), **self.reviews.status(request.principal, plan)}

    def review(self, request):
        require_scope(request.principal, 'approve')
        plan = self.plans.reviewable(request.principal, name(request.arguments['plan']))
        self.catalog.destination(plan.tenant, plan.destination)
        return self.reviews.record(request.principal, plan)

    def execute(self, request):
        require_scope(request.principal, 'run')
        plan = self.plans.owned(request.principal, name(request.arguments['plan']))
        return self.executor.execute(request.principal, plan)

from collections import OrderedDict
from dataclasses import dataclass
from secrets import token_urlsafe
from .errors import Refused, Conflict

@dataclass(frozen=True)
class Session:
    id: str
    token: str
    subject: str
    tenant: str
    credential_id: str
    expires: float

class Sessions:
    def __init__(self, credentials, settings, clock):
        self.credentials = credentials
        self.settings = settings
        self.clock = clock
        self.rows = OrderedDict()

    def prune(self):
        now = self.clock.now()
        for sid, session in list(self.rows.items()):
            if session.expires <= now:
                del self.rows[sid]

    def open(self, token):
        principal = self.credentials.authenticate(token)
        self.prune()
        if len(self.rows) >= self.settings.session_capacity:
            raise Conflict('session capacity')
        sid = token_urlsafe(24)
        session = Session(sid, token, principal.subject, principal.tenant,
                          principal.credential_id, self.clock.now() + self.settings.session_ttl)
        self.rows[sid] = session
        return {'session': sid, 'expires_in': self.settings.session_ttl}

    def resolve(self, sid):
        self.prune()
        if not isinstance(sid, str):
            raise Refused('session')
        session = self.rows.get(sid)
        if session is None:
            raise Refused('session')
        principal = self.credentials.authenticate(session.token)
        if (principal.subject, principal.tenant, principal.credential_id) != (
                session.subject, session.tenant, session.credential_id):
            raise Refused('session identity')
        return session, principal

    def close(self, sid):
        session, _ = self.resolve(sid)
        del self.rows[session.id]
        return {'closed': True}

    def count(self):
        self.prune()
        return len(self.rows)

def count(self):
        self.prune()
        return len(self.rows)
